export default function RegionsMapAbout() {
  const ref = useRef(null);
  useEffect(() => {
    if (!ref.current) return;
    const raf = requestAnimationFrame(() => {
      const svg = ref.current?.querySelector("svg");
      if (svg) initPulse(svg);
    });
    return () => cancelAnimationFrame(raf);
  }, []);

  return (
    <div className="rma-root">
      <div ref={ref} className="rma-svg-wrap" dangerouslySetInnerHTML={{ __html: SVG_MARKUP }} />
      {LABELS.map((l) => (
        <div key={l.region} className="rma-label" style={{ left:l.left, top:l.top }}>
          {l.name}
        </div>
      ))}
      <style>{css}</style>
    </div>
  );
}

function initPulse(svg) {
  const NS = "http://www.w3.org/2000/svg";
  const defs = svg.querySelector("defs");
  const grad = document.createElementNS(NS, "radialGradient");
  grad.setAttribute("id","rmaGrad");
  grad.innerHTML =
    '<stop offset="0%"  stop-color="rgba(120,165,255,1)"/>' +
    '<stop offset="30%" stop-color="rgba(35,110,245,0.75)"/>' +
    '<stop offset="65%" stop-color="rgba(6,86,238,0.18)"/>' +
    '<stop offset="100%" stop-color="rgba(6,86,238,0)"/>';
  defs.appendChild(grad);
  const layer = svg.querySelector(".pulse-layer");
  REGIONS.forEach((region, i) => {
    const group = svg.querySelector(`.region-group[data-region="${region}"]`);
    if (!group) return;
    const bbox = group.getBBox();
    const rMax = Math.sqrt(bbox.width**2 + bbox.height**2) / 2 * 1.05;
    const src = svg.querySelector("#" + PULSE_SOURCE[region]);
    let cx, cy;
    if (src) { const sb=src.getBBox(); cx=sb.x+sb.width/2; cy=sb.y+sb.height/2; }
    else { cx=bbox.x+bbox.width/2; cy=bbox.y+bbox.height/2; }
    const clip = document.createElementNS(NS,"g");
    clip.setAttribute("clip-path",`url(#clip-${region})`);
    const c = document.createElementNS(NS,"circle");
    c.setAttribute("cx",cx); c.setAttribute("cy",cy); c.setAttribute("r",rMax);
    c.setAttribute("class","rma-glow");
    c.style.animationDelay = `${i*0.6}s`;
    clip.appendChild(c); layer.appendChild(clip);
  });
}

const css = `
  .rma-root { position:relative; width:100%; }
  .rma-svg-wrap { width:100%; line-height:0; }
  .rma-svg-wrap svg { width:100%; height:auto; display:block; overflow:visible; }
  .rma-svg-wrap .map-context path,
  .rma-svg-wrap .region-group path {
    fill:rgba(255,255,255,0.045); stroke:rgba(255,255,255,0.09);
    stroke-width:0.4; vector-effect:non-scaling-stroke;
  }
  .rma-svg-wrap .pulse-layer { pointer-events:none; }
  .rma-svg-wrap .rma-glow {
    fill:url(#rmaGrad); transform-box:fill-box; transform-origin:center;
    animation:rmaSwipe 3s cubic-bezier(.25,.46,.45,.94) infinite;
  }
  @keyframes rmaSwipe {
    0%   { transform:scale(0); opacity:.9; }
    60%  { opacity:.22; }
    100% { transform:scale(1); opacity:0; }
  }
  .rma-label {
    position:absolute;
    transform:translate(-50%,-50%);
    pointer-events:none;
    font-family:'Inter',sans-serif;
    font-weight:300;
    font-size:clamp(10px,.85vw,13px);
    color:rgba(255,255,255,0.9);
    white-space:nowrap;
    letter-spacing:0.03em;
    padding:6px 14px;
    border-radius:999px;
    background:rgba(10,10,18,0.55);
    backdrop-filter:blur(12px);
    -webkit-backdrop-filter:blur(12px);
    border:0.5px solid rgba(255,255,255,0.12);
    box-shadow:inset 0 1px 1px rgba(255,255,255,0.07), 0 4px 24px rgba(0,0,0,0.45);
  }
  @media (prefers-reduced-motion:reduce) {
    .rma-svg-wrap .rma-glow { animation:none; opacity:.35; transform:scale(.55); }
  }
`;
